/* Iterative, closed interval [lo, hi]. Returns index or -1. */
int binary_search(const int a[], int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;      /* no overflow */
        if (a[mid] == target)      return mid;
        else if (a[mid] < target)  lo = mid + 1;
        else                       hi = mid - 1;
    }
    return -1;
}

/* Recursive version, same invariant */
int bs_rec(const int a[], int lo, int hi, int target) {
    if (lo > hi) return -1;
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == target) return mid;
    if (a[mid] < target)  return bs_rec(a, mid + 1, hi, target);
    return bs_rec(a, lo, mid - 1, target);
}

/* first index with a[i] >= target, in [0, n] */
int lower_bound(const int a[], int n, int target) {
    int lo = 0, hi = n;                   /* half-open [lo, hi) */
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else                 hi = mid;
    }
    return lo;
}

/* first index with a[i] > target: same loop with <= in the test */
int upper_bound(const int a[], int n, int target) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] <= target) lo = mid + 1;
        else                  hi = mid;
    }
    return lo;
}

/* smallest capacity so all weights ship in <= days */
int can_ship(const int w[], int n, int cap, int days) {
    int need = 1, cur = 0;
    for (int i = 0; i < n; i++) {
        if (cur + w[i] > cap) { need++; cur = 0; }
        cur += w[i];
    }
    return need <= days;
}
/* lo = max(w), hi = sum(w): same lower_bound loop, using can_ship */

double my_sqrt(double x) {               /* x >= 1 */
    double lo = 1.0, hi = x;
    for (int i = 0; i < 100; i++) {
        double mid = lo + (hi - lo) / 2;
        if (mid * mid < x) lo = mid; else hi = mid;
    }
    return lo;
}
